3,33.9533089],[-118.2434347,33.9533162],[-118.2442059,33.9533198],[-118.2441976,33.9542753],[-118.2474609,33.9542615],[-118.2474956,33.9533884],[-118.2475961,33.9533676],[-118.2489493,33.9533741],[-118.2491106,33.9492734],[-118.2490446,33.949273],[-118.2490839,33.9482685],[-118.2491497,33.9474654],[-118.2491524,33.9465587],[-118.2491546,33.9456792],[-118.2491767,33.9438133],[-118.2491906,33.9431813],[-118.2536533,33.9431859],[-118.2536519,33.943282],[-118.2536529,33.943282],[-118.2541213,33.9432825],[-118.254128,33.9426877],[-118.2541377,33.9418768],[-118.2541481,33.9409846],[-118.2541581,33.940105],[-118.2541682,33.9392534],[-118.2541733,33.9388215],[-118.2541794,33.9382773],[-118.2547576,33.9382797],[-118.2565451,33.938287],[-118.2586884,33.9382956],[-118.2586879,33.9378699],[-118.2586879,33.9378232],[-118.2581381,33.9378219],[-118.2569981,33.9377389],[-118.2565533,33.937608],[-118.2560881,33.9373979],[-118.2555211,33.9369739],[-118.2552371,33.9366609],[-118.2551711,33.9366059],[-118.2551701,33.9365879],[-118.2550721,33.9365229],[-118.2548881,33.9360669],[-118.2548744,33.9359085],[-118.2548171,33.9352489],[-118.2554501,33.9352109],[-118.2558013,33.9351813],[-118.2561819,33.9351179],[-118.2564276,33.9350793],[-118.2569422,33.9349629],[-118.2573494,33.9348504],[-118.2575431,33.9347909],[-118.2582291,33.9345679],[-118.2586866,33.9344177],[-118.2589623,33.9343343],[-118.260109,33.9339639],[-118.2613117,33.9335763],[-118.2621493,33.9333055],[-118.262761,33.9331032],[-118.2633471,33.9329141],[-118.2638631,33.9327508],[-118.2644649,33.932563],[-118.2647349,33.9324613],[-118.2648975,33.9324005],[-118.2651679,33.9323117],[-118.2651681,33.9325049],[-118.2657345,33.9323225],[-118.2667904,33.9319824],[-118.2673521,33.9318015],[-118.2692391,33.9311935],[-118.2693092,33.9312006],[-118.2694227,33.9312075],[-118.2695283,33.9312084],[-118.2695828,33.9312053],[-118.2696431,33.9311986],[-118.2704723,33.9310571],[-118.270547,33.9310474],[-118.2706474,33.9310396],[-118.2707215,33.9310376],[-118.2738892,33.9310228],[-118.2760719,33.9310167],[-118.2784559,33.93101],[-118.2790879,33.9310082],[-118.2795199,33.931007],[-118.2800913,33.9310054],[-118.2805792,33.931004],[-118.2806918,33.9297694],[-118.2808255,33.9287259],[-118.2826029,33.9287046],[-118.286969,33.9286953],[-118.2916794,33.928703]],[[-118.2991126,33.8472939],[-118.2991128,33.8481333],[-118.2991247,33.8560052],[-118.2991252,33.8581822],[-118.2980539,33.8581832],[-118.2970586,33.8581842],[-118.2970571,33.8568204],[-118.2970568,33.8562043],[-118.2970466,33.847289],[-118.2991126,33.8472939]],[[-118.2995159,33.7441506],[-118.2994364,33.7441503],[-118.2993679,33.7441501],[-118.2980193,33.7441459],[-118.2980226,33.7434095],[-118.2968404,33.7434058],[-118.2968549,33.7404063],[-118.2968545,33.7402387],[-118.2968667,33.7378012],[-118.3005765,33.7378133],[-118.3012757,33.737815],[-118.3091556,33.7378383],[-118.3091547,33.7380306],[-118.3091519,33.7387451],[-118.3091469,33.73891],[-118.3091362,33.7406407],[-118.3091364,33.7407783],[-118.3091314,33.7416273],[-118.3087922,33.7416264],[-118.3085661,33.741626],[-118.3085619,33.7416258],[-118.3043844,33.7416142],[-118.3041541,33.7416136],[-118.3041549,33.7414075],[-118.3041566,33.7408442],[-118.3041568,33.7407066],[-118.3041571,33.7405915],[-118.3041598,33.7397863],[-118.302418,33.7392746],[-118.3021886,33.7392741],[-118.3021877,33.7394115],[-118.3021834,33.740702],[-118.3030057,33.740704],[-118.3030035,33.741446],[-118.3030028,33.7416108],[-118.3016873,33.7416077],[-118.3016802,33.743256],[-118.3016794,33.7434209],[-118.2995193,33.7434141],[-118.2995159,33.7441506]]]}'), 4326),
  source = 'City of Los Angeles, NavigateLA Boundaries MapServer layer 13 "Council Districts" (maps.lacity.org/lahub/rest/services/Boundaries/MapServer/13), read 2026-10-20. This REPLACES the 2012-adopted map these rows previously held, which came from the third-party AGOL copy services5.arcgis.com/7nsPwEMP38bSkCjy Council_Districts/FeatureServer/0 (editingInfo.lastEditDate 2021-03-22, months before the current map took effect) and was mis-tagged la_city_geohub_council_districts_2024. VINTAGE PROVED against the LA County Registrar-Recorder precinct layer (public.gis.lacounty.gov Political_Boundaries MapServer 34, DST_CITY=LS / DIV_CITY) -- the layer the county builds BALLOTS from, the Columbus arbiter rule -- on 25 of 25 sampled cells where the 2012 and current maps disagree: 25 agree with THIS layer, 0 with the superseded one. The layer NAME field agrees with the sitting council 15/15 and is recorded as CORROBORATION ONLY, never as the vintage proof (an officeholder name can be current while the boundary is stale -- that is exactly how the 2012 map passed unnoticed: it carried "Nithya Raman", a sitting member).',
  imported_at = now()
WHERE ocd_id = 'ocd-division/country:us/state:ca/place:los_angeles/council_district:15' AND mtfcc = 'X0001';

DO $$
DECLARE n int; a numeric; cd text;
BEGIN
  -- 1. all 15 rows carry the new provenance
  SELECT count(*) INTO n FROM essentials.geofence_boundaries
   WHERE ocd_id LIKE 'ocd-division/country:us/state:ca/place:los_angeles/council_district:%'
     AND source LIKE 'City of Los Angeles, NavigateLA%';
  IF n <> 15 THEN RAISE EXCEPTION 'CA_0317: % of 15 LA council rows carry the new source', n; END IF;

  -- 2. nothing is left on the superseded tag
  SELECT count(*) INTO n FROM essentials.geofence_boundaries
   WHERE source = 'la_city_geohub_council_districts_2024';
  IF n <> 0 THEN RAISE EXCEPTION 'CA_0317: % rows still tagged la_city_geohub_council_districts_2024', n; END IF;

  -- 3. every polygon valid, SRID 4326, districts 1..15 exactly once
  SELECT count(*) INTO n FROM essentials.geofence_boundaries
   WHERE ocd_id LIKE 'ocd-division/country:us/state:ca/place:los_angeles/council_district:%'
     AND public.ST_IsValid(geometry) AND public.ST_SRID(geometry) = 4326;
  IF n <> 15 THEN RAISE EXCEPTION 'CA_0317: only % of 15 polygons are valid 4326', n; END IF;
  SELECT count(DISTINCT split_part(ocd_id, ':', 5)) INTO n FROM essentials.geofence_boundaries
   WHERE ocd_id LIKE 'ocd-division/country:us/state:ca/place:los_angeles/council_district:%';
  IF n <> 15 THEN RAISE EXCEPTION 'CA_0317: % distinct district numbers, want 15', n; END IF;

  -- 4. the city did not change size: total area within 1% of the 1,225.54 sq km the old rows summed to.
  --    This is the redistricting signature -- districts move, the union does not (the Lexington test).
  SELECT sum(public.ST_Area(geometry::public.geography))/1e6 INTO a FROM essentials.geofence_boundaries
   WHERE ocd_id LIKE 'ocd-division/country:us/state:ca/place:los_angeles/council_district:%';
  IF a < 1213.3 OR a > 1237.8 THEN RAISE EXCEPTION 'CA_0317: council districts now total % sq km, want 1225.5 +/-1%%', round(a, 2); END IF;

  -- 5. districts must not overlap one another (> 1000 sq m of shared interior is a real overlap)
  SELECT count(*) INTO n FROM essentials.geofence_boundaries x
   JOIN essentials.geofence_boundaries y
     ON y.ocd_id > x.ocd_id AND y.ocd_id LIKE 'ocd-division/country:us/state:ca/place:los_angeles/council_district:%'
   WHERE x.ocd_id LIKE 'ocd-division/country:us/state:ca/place:los_angeles/council_district:%'
     AND public.ST_Area(public.ST_Intersection(x.geometry, y.geometry)::public.geography) > 1000;
  IF n <> 0 THEN RAISE EXCEPTION 'CA_0317: % overlapping council district pairs', n; END IF;

  -- 6. END TO END, the reported address: 1338 N Ogden Dr (Census + OSM rooftop agree to ~2m) must now
  --    resolve through geofence -> district -> office -> current holder to Hugo Soto-Martinez in CD13.
  SELECT split_part(gb.ocd_id, ':', 5) INTO cd FROM essentials.geofence_boundaries gb
   WHERE gb.ocd_id LIKE 'ocd-division/country:us/state:ca/place:los_angeles/council_district:%'
     AND public.ST_Covers(gb.geometry, public.ST_SetSRID(public.ST_MakePoint(-118.359189363649, 34.09514458805), 4326));
  IF cd IS DISTINCT FROM '13' THEN RAISE EXCEPTION 'CA_0317: 1338 N Ogden Dr resolves to CD%, want CD13', coalesce(cd, 'NONE'); END IF;
  SELECT count(*) INTO n FROM essentials.geofence_boundaries gb
   JOIN essentials.districts d ON d.ocd_id = gb.ocd_id
   JOIN essentials.offices o ON o.district_id = d.id
   JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id IS NOT NULL
   JOIN essentials.politicians p ON p.id = och.politician_id
   WHERE gb.ocd_id LIKE 'ocd-division/country:us/state:ca/place:los_angeles/council_district:%'
     AND public.ST_Covers(gb.geometry, public.ST_SetSRID(public.ST_MakePoint(-118.359189363649, 34.09514458805), 4326))
     AND p.full_name = 'Hugo Soto-Martinez';
  IF n <> 1 THEN RAISE EXCEPTION 'CA_0317: Ogden Dr does not reach Hugo Soto-Martinez (% rows)', n; END IF;

  -- 7. and the previously-shown member must no longer cover that point
  SELECT count(*) INTO n FROM essentials.geofence_boundaries gb
   WHERE gb.ocd_id = 'ocd-division/country:us/state:ca/place:los_angeles/council_district:4'
     AND public.ST_Covers(gb.geometry, public.ST_SetSRID(public.ST_MakePoint(-118.359189363649, 34.09514458805), 4326));
  IF n <> 0 THEN RAISE EXCEPTION 'CA_0317: CD4 still covers 1338 N Ogden Dr'; END IF;

  RAISE NOTICE 'CA_0317 OK: 15 LA council districts on the current map; 1338 N Ogden Dr -> CD13 Hugo Soto-Martinez';
END $$;

COMMIT;
